package com.docsaas.api.service;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Comparator;
import java.util.stream.Stream;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import jakarta.annotation.PostConstruct;

/**
 * Local-disk file storage. Keys are always generated by the server
 * (e.g. "jobs/{uuid}/in/0"), so user-supplied filenames never touch the filesystem.
 */
@Service
public class StorageService {

    private static final Logger log = LoggerFactory.getLogger(StorageService.class);

    @Value("${docsaas.storage.dir}")
    private String storageDir;

    private Path root;

    @PostConstruct
    void init() throws IOException {
        root = Path.of(storageDir).toAbsolutePath().normalize();
        Files.createDirectories(root);
        log.info("File storage root: {}", root);
    }

    public Path resolve(String key) {
        Path path = root.resolve(key).normalize();
        if (!path.startsWith(root)) {
            throw new IllegalArgumentException("Storage key escapes storage root");
        }
        return path;
    }

    public Path save(String key, InputStream in) throws IOException {
        Path target = resolve(key);
        Files.createDirectories(target.getParent());
        Files.copy(in, target, StandardCopyOption.REPLACE_EXISTING);
        return target;
    }

    public void deleteQuietly(String key) {
        try {
            Files.deleteIfExists(resolve(key));
        } catch (IOException e) {
            log.warn("Could not delete stored file {}", key);
        }
    }

    /** Recursively deletes a directory under the storage root (e.g. a job's folder). */
    public void deleteTreeQuietly(String key) {
        Path dir = resolve(key);
        if (!Files.exists(dir)) {
            return;
        }
        try (Stream<Path> walk = Files.walk(dir)) {
            walk.sorted(Comparator.reverseOrder()).forEach(p -> {
                try {
                    Files.deleteIfExists(p);
                } catch (IOException e) {
                    log.warn("Could not delete {}", p);
                }
            });
        } catch (IOException e) {
            log.warn("Could not delete directory {}", key);
        }
    }
}
